        if (DB::connection()->getDriverName() === 'pgsql') {
            $seq = DB::selectOne("SELECT pg_get_serial_sequence('hardwares','id') as seq");
            if ($seq && $seq->seq) {
                DB::statement('SELECT setval(?, (SELECT COALESCE(MAX(id), 0) FROM hardwares))', [$seq->seq]);
