    public static function notifyUnit(int $unitId, string $type, string $title, ?string $body = null, ?string $url = null): void
    {
        $userIds = User::whereHas('units', fn ($q) => $q->where('units.id', $unitId))
            ->pluck('id');

        if ($userIds->isEmpty()) {
