                    ->where(function ($query) use ($words) {
                        foreach ($words as $word) {
                            $query->where(function ($inner) use ($word) {
                                $inner->where('subject', 'like', "%{$word}%")
                                      ->orWhere('ticket_code', 'like', "%{$word}%");
                            });
                        }
                    })
